interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number

?: number;
  report?: string;
}

/* ------------------------------------------------------------------ *
 *  Shared processing state threaded through every event handler.
 * ------------------------------------------------------------------ */
interface Ctx {
  stock: Record<string, number>;
  orders

: number;
}

type Handler = (ctx: Ctx, event: Record<string, unknown>, index

/* ------------------------------------------------------------------ *
 *  Small, single-purpose helpers the handlers share.
 * ------------------------------------------------------------------ */

/** Stock on hand for an item, treating a missing key as zero. */
function stockOf(ctx: Ctx, item: string): number {
  return ctx.stock[item] === undefined ? 0 : ctx.stock[item];
}

/** Walk the backorder queue and fill any entries that now fit in stock. */
function fulfillQueue(ctx: Ctx): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const id = ctx.queue[position];
    const want = ctx.wants[id];
    const onHand = stockOf(ctx, want.item);
    if (onHand >=

 want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[id] = { item: want.item, qty: want.qty };
      ctx.orders[id] = "reserved";
      delete ctx.wants[id];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

/** Add `qty` to an item's stock, then give queued orders first chance at it. */
function addStock(ctx: Ctx, item: string, qty: number): void {
  ctx.stock[item] = stockOf(ctx, item) + qty;
  fulfillQueue(ctx);
}

function badEvent(index: number, why: string): string {
  return "event " + index + ": " + why;
}

/* ------------------------------------------------------------------ *
 *  One handler per event type. Each returns an error message (or
 *  undefined when the event was applied).
 * ------------------------------------------------------------------ */

function handleOrder(ctx: Ctx, e: Record<string, unknown>, i

: number): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return badEvent(i, "bad id");
  if (ctx.orders[e.id] !== undefined) return badEvent(i, "duplicate order");
  if (typeof e.item !== "string" || e.item.length === 0) return badEvent(i, "bad item");
  if (!Number.isInteger(e.qty) || (e.qty as number) < 1) return badEvent(i, "bad qty");
  const item = e.item;
  const qty = e.qty as number;
  if (stockOf(ctx, item) >= qty) {

    ctx.stock[item] = stockOf(ctx, item) - qty;
    ctx.reserved[e.id] = { item, qty };
    ctx.orders[e.id] = "reserved";
  } else {
    ctx.queue.push(e.id);
    ctx.wants[e.id] = { item, qty };
    ctx.orders[e.id] = "backordered";
  }
  return undefined;
}

function handleCancel(ctx: Ctx, e: Record<string, unknown>, i: number

): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return badEvent(i, "bad id");
  const holding = ctx.reserved[e.id];
  if (holding !== undefined) {
    addStock(ctx, holding.item, holding.qty);
    delete ctx.reserved[e.id];
    ctx.orders[e.id] = "cancelled";
  } else if (ctx.orders[e.id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(e.id), 1);
    delete ctx.wants[e.id];
    ctx.orders[e.id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

function handleShip(ctx: Ctx, e: Record<string, unknown>, i

: number): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return badEvent(i, "bad id");
  if (e.qty !== undefined && (!Number.isInteger(e.qty) || (e.qty as number) < 1)) {
    return badEvent(i, "bad qty");
  }
  const holding = ctx.reserved[e.id];
  if (holding === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (e.qty === undefined || (e.qty as number) === holding.qty) {
    delete ctx.reserved[e.id];
    ctx.orders[e.id] = "shipped";
  } else if ((e.qty as number) < holding.qty) {
    holding.qty = holding.qty - (e.qty as number);
    ctx.orders[e.id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

function handleRestock(ctx: Ctx, e: Record<string, unknown>, i: number):

 string | undefined {
  if (typeof e.item !== "string" || e.item.length === 0) return badEvent(i, "bad item");
  if (!Number.isInteger(e.qty) || (e.qty as number) < 1) return badEvent(i, "bad qty");
  addStock(ctx, e.item, e.qty as number);
  return undefined;
}

function handleExpire(ctx: Ctx, e: Record<string, unknown>, i: number

): string | undefined {
  if (typeof e.id !== "string" || e.id.length === 0) return badEvent(i, "bad id");
  const holding = ctx.reserved[e.id];
