import { processO } from './o';
import { processN } from './n';
function randInt(n:number){ return Math.floor(Math.random()*n); }
function scenario(): any {
  const items=['A','B','C'];
  const stock:any={};
  for(const it of items){ if(Math.random()<0.7) stock[it]=randInt(6); }
  const events:any=[];
  const ids=[];
  const nEvents=randInt(12);
  for(let k=0;k<nEvents;k++){
    const types=['order','cancel','ship','restock','expire','bogus'];
    const t=types[randInt(types.length+ (Math.random()<0.15?1:0))]; // weighted, sometimes bogus
    const ty = Math.random()<0.75 ? ['order','cancel','ship','restock','expire'][randInt(5)] : [undefined,'order','cancel','ship','restock','expire','bogus'][randInt(7)];
    const ev:any={ type: Math.random()<0.08? 'bogus': (['order','cancel','ship','restock','expire'][randInt(5)]) };
    if(Math.random()<0.1) delete ev.type;
    if(Math.random()<0.8) ev.id = 'id'+randInt(8);
    if(Math.random()<0.7) ev.item = items[randInt(3)];
    if(Math.random()<0.7) ev.qty = randInt(6);
    events.push(ev);
  }
  // malformed input occasionally
  if(Math.random()<0.06) return null;
  if(Math.random()<0.06) return 42;
  if(Math.random()<0.06) return { stock: 'x', events: [] };
  if(Math.random()<0.05) return { stock, events: 'x' };
  return { stock, events };
}
let fails=0;
for(let t=0;t<200000;t++){
  const s=scenario();
  let a,b;
  try{ a=processO(s as any); }catch(e){ a='THROW:'+e; }
  try{ b=processN(s as any); }catch(e){ b='THROW:'+e; }
  if(JSON.stringify(a)!==JSON.stringify(b)){
    fails++;
    if(fails<10){ console.log('MISMATCH', JSON.stringify(s), '\n O:', JSON.stringify(a), '\n N:', JSON.stringify(b)); }
  }
}
console.log('fails:', fails);
EOF
